// Parse Athena Page
//
// Input : one item = one raw Athena GetQueryResults response (one page, up to 1000 rows).
// Output: one item = { page, nextToken, rowCount, range, values } — this page as the 2D array
//         that Append Page to Sheet sends to the Sheets API. Page 0 carries the header row first.
//
// Runs once per page, and every page is appended to the sheet straight away, so no node ever
// holds the whole result in a single item. Export Summary adds up the rowCount of every run.

// 100 pages x 1000 rows. A result this large means a filter has gone missing — and the
// spreadsheet's own 10,000,000-cell limit is the real cap (see the docs) — investigate before raising it.
const MAX_PAGES = 100;

// Sheet columns, in SQL order. Headers are the Athena column names (the SQL aliases).
// `number` columns are sent as numbers so the sheet can sum and sort them; everything else as text,
// so phone numbers keep their + and leading 0, ids are never reformatted and dates stay as Athena
// printed them.
const COLUMNS = [
  {
    "name": "Brand",
    "type": "text"
  },
  {
    "name": "Account",
    "type": "text"
  },
  {
    "name": "Risk business segment",
    "type": "text"
  },
  {
    "name": "Risk casino segment",
    "type": "text"
  },
  {
    "name": "Phone",
    "type": "text"
  },
  {
    "name": "Email",
    "type": "text"
  },
  {
    "name": "Email verified",
    "type": "text"
  },
  {
    "name": "Aff id",
    "type": "text"
  },
  {
    "name": "Last Deposit date",
    "type": "text"
  },
  {
    "name": "Deposit count 12M",
    "type": "number"
  },
  {
    "name": "Deposit amount 12M",
    "type": "number"
  },
  {
    "name": "Withdrawal amount 12M",
    "type": "number"
  },
  {
    "name": "Average bet Casino 12M",
    "type": "number"
  },
  {
    "name": "Average deposit 12M",
    "type": "number"
  },
  {
    "name": "GGR Casino 12M",
    "type": "number"
  },
  {
    "name": "Last withdrawal amount",
    "type": "number"
  },
  {
    "name": "Margin Casino 12M, %",
    "type": "number"
  },
  {
    "name": "NGR Casino 12M",
    "type": "number"
  },
  {
    "name": "Total Casino Clear bonus amount 12M",
    "type": "number"
  },
  {
    "name": "Withdrawal count 12M",
    "type": "number"
  },
  {
    "name": "Registration date",
    "type": "text"
  },
  {
    "name": "First Deposit date",
    "type": "text"
  },
  {
    "name": "First Bet Casino date",
    "type": "text"
  },
  {
    "name": "Last Bet Casino date",
    "type": "text"
  },
  {
    "name": "Bonus rate Casino 12M, %",
    "type": "number"
  },
  {
    "name": "Last Withdrawal date",
    "type": "text"
  },
  {
    "name": "LDD",
    "type": "number"
  },
  {
    "name": "Hold %",
    "type": "number"
  },
  {
    "name": "Emails sent 12M",
    "type": "number"
  },
  {
    "name": "Emails opened 12M",
    "type": "number"
  },
  {
    "name": "Email open rate 12M, %",
    "type": "number"
  },
  {
    "name": "Last email open date",
    "type": "text"
  }
];

/** Athena returns every value as a string, or omits VarCharValue entirely for NULL. */
function cellValue(cell) {
  if (cell === null || cell === undefined) return null;
  const raw = cell.VarCharValue;
  if (raw === null || raw === undefined) return null;
  return String(raw);
}

/** NULL becomes an empty cell. Unparseable numbers also become empty, never NaN. */
function toCell(raw, type) {
  if (raw === null || raw === undefined) return '';
  const text = String(raw).trim();
  if (text === '') return '';
  if (type !== 'number') return text;
  const parsed = Number(text);
  return Number.isFinite(parsed) ? parsed : '';
}

/** 1 -> A, 26 -> Z, 27 -> AA, 33 -> AG. */
function columnLetter(n) {
  let s = '';
  while (n > 0) {
    const r = (n - 1) % 26;
    s = String.fromCharCode(65 + r) + s;
    n = Math.floor((n - 1) / 26);
  }
  return s;
}

const page = $runIndex;

if (page >= MAX_PAGES) {
  throw new Error(
    `Athena result exceeds ${MAX_PAGES} pages (${MAX_PAGES * 1000} rows). The export query ` +
      'has probably lost a filter — investigate before raising MAX_PAGES. The tab holds the pages written so far.',
  );
}

const inputItems = $input.all();
if (inputItems.length !== 1) {
  throw new Error(
    `Parse Athena Page expected exactly 1 input item from Athena, received ${inputItems.length}.`,
  );
}

const response = inputItems[0].json ?? {};
const resultSet = response.ResultSet;
if (!resultSet || !Array.isArray(resultSet.Rows)) {
  throw new Error(
    'Unexpected Athena response: ResultSet.Rows is missing. Check the Get Athena Results Page node output.',
  );
}

const athenaColumns = (resultSet.ResultSetMetadata?.ColumnInfo ?? []).map((column) => column?.Name);
const missingColumns = COLUMNS.map((c) => c.name).filter((name) => !athenaColumns.includes(name));
if (missingColumns.length > 0) {
  throw new Error(
    `Athena result is missing column(s): ${missingColumns.join(', ')}. The export SQL and this ` +
      'node have drifted apart — update both together.',
  );
}

// Athena prepends a header row, on the first page only.
let rows = resultSet.Rows;
if (page === 0) {
  const firstRowValues = (rows[0]?.Data ?? []).map(cellValue);
  const firstRowIsHeader =
    firstRowValues.length === athenaColumns.length &&
    firstRowValues.every((value, index) => value === athenaColumns[index]);
  if (firstRowIsHeader) rows = rows.slice(1);
}

// Map each sheet column to its position in the Athena result, so column order in the SQL
// may differ from the sheet without breaking anything.
const columnIndex = COLUMNS.map((c) => athenaColumns.indexOf(c.name));

const values = [];
if (page === 0) values.push(COLUMNS.map((c) => c.name));

let rowCount = 0;
for (const row of rows) {
  const cells = row?.Data ?? [];
  const record = COLUMNS.map((c, i) => toCell(cellValue(cells[columnIndex[i]]), c.type));
  if (record.every((value) => value === '')) continue;
  values.push(record);
  rowCount += 1;
}

const tab = String($('Config').first().json.outputSheetTab ?? '').trim();
if (tab === '') {
  throw new Error('Config.outputSheetTab is empty. Set it to the name of the tab to overwrite.');
}
const quotedTab = `'${tab.replace(/'/g, "''")}'`;

return [
  {
    json: {
      page,
      nextToken: response.NextToken ?? null,
      rowCount,
      // values:append finds the table in this range and writes below its last row.
      range: `${quotedTab}!A:${columnLetter(COLUMNS.length)}`,
      values,
    },
  },
];

// Export Summary
//
// Input : one item = the Sheets response of the last Append Page to Sheet call.
// Output: one item = { tab, pages, rowCount, finishedAt } — what this run wrote.
//
// Adds up every run of Parse Athena Page. Only for the execution log: look here when the
// tab looks too short or too long.

const inputItems = $input.all();
if (inputItems.length !== 1) {
  throw new Error(`Export Summary expected exactly 1 input item, received ${inputItems.length}.`);
}

let pages = 0;
let rowCount = 0;
for (let run = 0; run < 100000; run++) {
  let pageItems;
  try {
    pageItems = $('Parse Athena Page').all(0, run);
  } catch (error) {
    break;
  }
  if (!Array.isArray(pageItems) || pageItems.length === 0) break;
  if (pageItems.length !== 1) {
    throw new Error(`Parse Athena Page run ${run} produced ${pageItems.length} items, expected 1.`);
  }
  pages += 1;
  rowCount += Number(pageItems[0].json.rowCount ?? 0);
}

return [
  {
    json: {
      tab: $('Config').first().json.outputSheetTab,
      pages,
      rowCount,
      lastUpdatedRange: inputItems[0].json.updates?.updatedRange ?? null,
      finishedAt: $now.toISO(),
    },
  },
];
